-- ============================================================================
-- B5 FOLLOW-ON W1 (grade integrity): earthmodel.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 4 and
-- the annotations in docs/graded-field-audit/annot/earthmodel.json. Owner
-- approved D1 to D7 as recommended, 2026-09-21.
--
-- ADVANCED
--   krige_at_w1 was prompt-given: the prompt called it the exactness check and
--   the tile's unit string printed "W1 is 0.3150", so W1's logged porosity
--   passed without kriging anything. It is replaced by a measured per-block
--   kriging output, the porosity jump across the fault on the y = 2200 row
--   (block 0 node at x 1600 minus block 1 node at x 1550, signed), read from the
--   Population explorer's "Jump across the fault on this row" tile at 6 dp:
--   -0.023016035393453593. tol 5e-5: the nearest variogram options (nugget
--   0.00025 with range 300, 8.8e-5 away; range 600, 1.9e-4) and the trend and
--   constant seams (-0.0210, -0.0287) all fail. The prompt now states the
--   variogram. krige_probe keeps its key; a probe readout with x and y inputs
--   (default 2000, 2300) now prints it at 6 dp, and the lead tightens its tol
--   0.001 -> 0.0002.
--   RE-KEY krige_at_w1 (expected 0.315, tol 0.0005)
--       -> fault_jump_y2200 'Porosity jump across the fault on the y = 2200 row' v/v, expected -0.023016035393453593, tol 5e-05
--   TIGHTEN krige_probe (expected 0.2914277719922997) tol 0.001 -> 0.0002:
--       the naive mean 0.290516 shown by default sits 0.00091 off and passed; the
--       new probe tile prints 6 decimals
--   PROMPT was: the kriged porosity at (1500, 2500) and AT well W1 (the
--   exactness check: simple kriging with a nugget below the sill honors the
--   data),
--   PROMPT now: the kriged porosity at (1500, 2500), and the porosity jump
--   across the fault on the y = 2200 row of the per-block kriged map (the block
--   0 node at x 1600 minus the block 1 node at x 1550, sign kept), both by
--   simple kriging on the stated spherical variogram (sill 0.0025, nugget
--   0.00025, range 900 m),
--
-- WHAT DOES NOT MOVE. Every other field (key, label, unit, expected, tol and
-- position), the title, dataset, status and the row itself.
--
-- ATTEMPTS. Tiers whose graded key or tolerance moves: earthmodel/advanced.
-- Before it writes, the file counts academy_capstone_attempts on each and
-- REFUSES if any exist, unless D5 allowlists that tier with the exact attempt
-- ids (allowlist: empty). Stored scores are never touched.
--
-- GUARDS. Each row must hold EITHER its published prompt (by md5) and fields
-- (exact jsonb) as the post-20261023 scratch replay has them (it is
-- rewritten), OR its W1 form (left alone). Anything else raises and the whole
-- file rolls back. A file that will write first checks the round-off
-- post-state (20261023*) and refuses without it. Generated by
-- docs/graded-field-audit/w1_capstones.py. SAFE TO RE-RUN: a second run
-- writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_ids      jsonb;
  v_extra    jsonb;
  v_allow    jsonb := '{}'::jsonb;  -- D5 allowlist: 'course/tier' -> attempt ids signed off
  v_s0       text;
begin
  -- earthmodel / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'earthmodel' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w1 earthmodel refused: earthmodel/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '6c4d28733d59c286b46986a741471a0e' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.001, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "krige_at_w1", "tol": 0.0005, "unit": "v/v", "label": "Kriged porosity at W1 (1100, 2100)", "expected": 0.315}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb then 'old'
              when md5(prompt) = '3072aa8bddbc113c8999c8f84204b99e' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb then 'new'
              when md5(prompt) = '58aebea2da84ab88697ccc64d18be8a7' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'earthmodel' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w1 earthmodel refused: earthmodel/advanced matches neither its published form (prompt md5 6c4d28733d59c286b46986a741471a0e) nor its W1 form (prompt md5 3072aa8bddbc113c8999c8f84204b99e), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W1 form
  if v_s0 = 'new' then
    raise notice 'w1 earthmodel: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- the round-off batch (20261023*) must be applied first: its rows are this file's base
  if exists (select 1 from public.academy_capstones where app_slug = 'cementing' and tier = 'advanced' and active and md5(prompt) <> '7e7412057740dcb01936e298c2026745')
     or exists (select 1 from public.academy_capstones where app_slug = 'casingtubing' and tier = 'advanced' and active and md5(prompt) <> 'f7e6749b9be66d4dbc7e692745d656d7')
     or exists (select 1 from public.academy_capstones where app_slug = 'gaswell' and tier = 'advanced' and active and md5(prompt) <> '07f6076362de4a93714236cc10af4012')
     or exists (select 1 from public.academy_capstones where app_slug = 'wellcontrol' and tier = 'beginner' and active and md5(dataset) <> '228b1d1a73f0474291f6142741bab7b2')
     or exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                 where c.app_slug = 'fiscal' and c.tier = 'intermediate' and c.active and f->>'key' = 'psc_npv_musd'
                   and (f->>'tol')::float8 <> 0.05) then
    raise exception 'w1 earthmodel refused: the round-off batch (20261023*) is not applied on this database; apply it first (/root/roundoff-apply/apply.sh apply --prod)';
  end if;

  -- ATTEMPTS. A tier whose graded key or tolerance this file moves must hold no
  -- capstone attempt (a stored score is never re-scored, but a learner could be
  -- graded differently on a retry of the same brief), unless D5 allowlists it
  -- with the exact attempt ids signed off. Any other attempt refuses.
  if v_s0 = 'old' then
    select coalesce(jsonb_agg(a.id::text order by a.created_at, a.id), '[]'::jsonb) into v_ids
      from public.academy_capstone_attempts a where a.app_slug = 'earthmodel' and a.tier = 'advanced';
    if jsonb_array_length(v_ids) > 0 then
      if v_allow ? 'earthmodel/advanced' then
        select coalesce(jsonb_agg(x), '[]'::jsonb) into v_extra
          from jsonb_array_elements(v_ids) x where not (v_allow->'earthmodel/advanced') @> jsonb_build_array(x);
        if jsonb_array_length(v_extra) > 0 then
          raise exception 'w1 earthmodel refused: earthmodel/advanced holds % attempt(s) outside its D5 allowlist: %', jsonb_array_length(v_extra), v_extra;
        end if;
        raise notice 'w1 earthmodel: earthmodel/advanced holds % allowlisted attempt(s) (D5 sign-off); their stored scores are not touched', jsonb_array_length(v_ids);
      else
        raise exception 'w1 earthmodel refused: earthmodel/advanced holds % capstone attempt(s) (%) and this file moves its graded key or tolerance; sign the tier off under D5 (allowlist with these ids) or hold it', jsonb_array_length(v_ids), v_ids;
      end if;
    end if;
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'Label the model with the fault polygon and run everything per block: the block-1 node count, the plane-trend porosity at (1250, 2250), the kriged porosity at (1500, 2500), and the porosity jump across the fault on the y = 2200 row of the per-block kriged map (the block 0 node at x 1600 minus the block 1 node at x 1550, sign kept), both by simple kriging on the stated spherical variogram (sill 0.0025, nugget 0.00025, range 900 m), zone A''s interval-weighted porosity in block 0, and zone A''s bulk rock volume in block 1.',
           fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb
     where app_slug = 'earthmodel' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w1 earthmodel refused: earthmodel/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = '3072aa8bddbc113c8999c8f84204b99e' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb)
        or (md5(prompt) = '58aebea2da84ab88697ccc64d18be8a7' and fields = '[{"key": "block1_cells", "tol": 0, "unit": "count", "label": "Block 1 node count", "expected": 174}, {"key": "trend_probe", "tol": 0.001, "unit": "v/v", "label": "Trend porosity at (1250, 2250)", "expected": 0.3075}, {"key": "krige_probe", "tol": 0.0002, "unit": "v/v", "label": "Kriged porosity at (1500, 2500)", "expected": 0.2914277719922997}, {"key": "fault_jump_y2200", "tol": 5e-05, "unit": "v/v", "label": "Porosity jump across the fault on the y = 2200 row", "expected": -0.023016035393453593}, {"key": "phi_block0", "tol": 0.001, "unit": "v/v", "label": "Zone A weighted porosity, block 0", "expected": 0.28631191845445614}, {"key": "bulk_a_block1", "tol": 0.01, "unit": "10^6 m3", "label": "Zone A bulk volume in block 1", "expected": 13.998749999999998}]'::jsonb) from public.academy_capstones where app_slug = 'earthmodel' and tier = 'advanced' and active) is not true then
    raise exception 'w1 earthmodel refused: earthmodel/advanced does not read back as its W1 form';
  end if;

  raise notice 'w1 earthmodel: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
